import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"Collect a support bundle","description":"","frontmatter":{},"headers":[],"relativePath":"support-bundle.md","filePath":"support-bundle.md","lastUpdated":1794098595000}'),i={name:"support-bundle.md"};function o(r,e,l,d,p,h){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="collect-a-support-bundle" tabindex="-1">Collect a support bundle <a class="header-anchor" href="#collect-a-support-bundle" aria-label="Permalink to &quot;Collect a support bundle&quot;">​</a></h1><p>An operator can create a readable JSON file on their own machine containing an allow-listed set of operational metadata, with no logs by default; review it before sharing. Nothing is uploaded automatically. Allowed fields such as custom image tags or numeric settings can still hold values you did not expect, so review the file before you share it.</p><p><strong>Edition:</strong> Community and Enterprise · <strong>Who:</strong> cluster operator with an AgentHub administrator credential</p><p>This requires Open AgentHub 1.23.0 or later. Use the collector from the release you run (replace <code>v1.23.0</code> with your version): <a href="https://github.com/open-agenthub/open-agenthub/blob/v1.23.0/scripts/support-bundle.py" target="_blank" rel="noreferrer">scripts/support-bundle.py</a>. Save it locally. Requirements: Python <strong>3.9+</strong>, kubectl <strong>1.34+</strong> (within one minor version of your cluster), and Helm <strong>3.12+</strong> or <strong>4.x</strong>. No pip packages are needed.</p><h2 id="create-the-file" tabindex="-1">Create the file <a class="header-anchor" href="#create-the-file" aria-label="Permalink to &quot;Create the file&quot;">​</a></h2><p>Your current kubectl context must point to your installation. You need permission to read pods, events, deployments and the <code>agenthub-config</code> ConfigMap in the release namespace. Helm also needs its normal release metadata read permissions. The collector never requests a Kubernetes Secret object directly, but Helm may read its stored release record. Raw Helm values stay in memory and never become a file.</p><p>Forward the backend service in one terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port-forward</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service/agenthub-backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:80</span></span></code></pre></div><p>In a second terminal, use Bash&#39;s hidden input to pass your credential through standard input:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Administrator credential: &#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> support_credential</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;\\n&#39;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s\\n&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$support_credential</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> support-bundle.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --namespace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --admin-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> support-bundle.json</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> support_credential</span></span></code></pre></div><p>For API-key login, enter the installation&#39;s existing API key. For OIDC login, enter a current access token for an administrator; a normal user&#39;s token receives <strong>403</strong>. Obtain that token through your organisation&#39;s normal sign-in process. Do not paste the credential into a command argument or inline, enable shell tracing, or save it in the bundle. The collector never prints it. The collector sends the credential as a bearer token to the backend address you give. It accepts only HTTPS or a local port-forward and does not follow redirects. Point it only at your own instance.</p><p>The command creates a new file with permissions <code>0600</code> (owner only) on Linux and macOS file systems and refuses to overwrite an existing file. Open and review the JSON before sharing it through a channel agreed with support. Remove the local copy when you no longer need it. Collection errors produce a generic message so an upstream error cannot echo credentials into diagnostic output.</p><h2 id="what-is-included" tabindex="-1">What is included <a class="header-anchor" href="#what-is-included" aria-label="Permalink to &quot;What is included&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Included</th></tr></thead><tbody><tr><td>Versions</td><td>Chart/application version and backend/configured runtime image tags; registry hosts and arbitrary custom tags are omitted</td></tr><tr><td>Pods</td><td>Component, phase, readiness, restart counts and pod counts in the release namespace; unknown component labels become <code>other</code>; no pod names</td></tr><tr><td>Events</td><td>Counts of fixed event reason categories in the last 60 minutes; no messages or object names</td></tr><tr><td>Helm values</td><td>Selected boolean and integer settings, such as replica counts, database pool sizes and feature flags; all other fields omitted</td></tr><tr><td>Database</td><td>Recognised <code>schema_scripts</code> names and application timestamps; no SQL or session data; <code>null</code>/<code>unavailable</code> if the tracking query fails</td></tr><tr><td>Licence</td><td>Verified edition, validity, expiry, included seat count and used seat count; no licence token, customer details or instance key</td></tr><tr><td>OIDC</td><td>Whether authority, client ID and audience are configured; no URLs, IDs or secrets</td></tr></tbody></table><p>Use <code>--event-minutes N</code> for a window from 1 to 1440 minutes. Unknown fields and values are omitted instead of copied. Custom tags display as <code>omitted</code>. The sessions namespace is never queried separately. No session records, prompts, transcripts, file contents, user lists, email addresses, secret values or Kubernetes Secret data are included.</p><h2 id="optional-backend-logs" tabindex="-1">Optional backend logs <a class="header-anchor" href="#optional-backend-logs" aria-label="Permalink to &quot;Optional backend logs&quot;">​</a></h2><p><strong>Logs can contain personal data and user-chosen names. Agree on sending logs with the provider beforehand (DPA), and review the file before sharing it.</strong> Logs are absent by default.</p><p>Add <code>--include-backend-logs --log-lines 200</code> to the command to examine the last 200 lines from each backend pod. The range is 1 to 10000. This requires pod log permissions. Only four exact framework lifecycle messages are retained: application started, application shutting down, production hosting environment and <code>/app</code> content root. Lines that look like tokens, unknown messages and multiline continuation lines are discarded entirely. This intentionally excludes most application logs; the bundle also reports how many lines were dropped. No agent/runtime, database or other component logs are collected. A warning appears both on the terminal and in the JSON.</p>`,18)])])}const k=t(i,[["render",o]]);export{u as __pageData,k as default};
